package com.testora;
import com.testora.config.DBConnection;import com.testora.judge.JudgeQueue;import com.testora.model.*;import com.testora.service.AuthService;import com.testora.ui.*;import com.testora.util.ConsoleUtil;import java.util.*;
/** Application entry point and unauthenticated console menu. */
public class Main {public static void main(String[] args){try(Scanner in=new Scanner(System.in);JudgeQueue judges=new JudgeQueue(Math.max(1,Runtime.getRuntime().availableProcessors()/2))){System.out.println("Testora | DB health: "+(DBConnection.healthCheck()?"connected":"not connected"));AuthService auth=new AuthService();while(true){System.out.println("1 Login  2 Register student  0 Exit");int c=ConsoleUtil.readInt(in,"> ");if(c==0)return;var r=c==1?auth.login(ConsoleUtil.read(in,"Email: "),ConsoleUtil.read(in,"Password: ")):auth.register(ConsoleUtil.read(in,"Name: "),ConsoleUtil.read(in,"Email: "),ConsoleUtil.read(in,"Password: "));System.out.println(r.message());if(r.success()){User u=r.data();Menu m=u.getRole()==Role.STUDENT?new StudentMenu(in,u,judges):u.getRole()==Role.FACULTY?new FacultyMenu(in,u):new AdminMenu(in,u);m.show();}}}}}
